function _shuffle(arr) {
  const a = [...arr]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

export function shuffleDeck() {
  const pool = _shuffle(ENTRIES)
  const deck = []
  for (let i = 0; i + 9 < pool.length; i += 10) {
    deck.push({
      id: deck.length,
      front: pool.slice(i, i + 5),
      back:  pool.slice(i + 5, i + 10),
    })
  }
  return deck
}
